import React, { useState } from "react";
import { Card, Breadcrumb, Form, Input, Button, Steps, Row, Col, Spin } from "antd";
import { UserOutlined, CheckCircleOutlined, LoadingOutlined } from "@ant-design/icons";
import PageHeader from "components/layout-components/PageHeader";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { useMutation } from "@apollo/client";
import {
  InviteStaff,
  InviteStaffArgs,
  InviteStaffRes,
} from "graphql-src/staff/mutations";

const { Step } = Steps;

const StepsContainer = styled(Row)`
  margin: 0 0 40px 0;
`;

const AddStaff = () => {
  const [step, setStep] = useState(0);
  const [submitting, setSubmitting] = useState(false);

  const layout = {
    labelCol: { span: 4 },
    wrapperCol: { span: 8 },
  };

  const [inviteStaff] = useMutation<InviteStaffRes, InviteStaffArgs>(
    InviteStaff,
    {
      onCompleted: () => {
        setStep(1)
        setSubmitting(false)
      },
    }
  );

  interface HandleSubmitArgs {
    email: string;
    name: string;
  }

  const handleSubmit = ({ email, name }: HandleSubmitArgs) => {
    setSubmitting(true)
    inviteStaff({
      variables: {
        email,
        name,
      },
    });
  };

  return (
    <div>
      <PageHeader
        display={true}
        title="Add Staff Member"
        breadcrumbs={
          <Breadcrumb>
            <Breadcrumb.Item>Home</Breadcrumb.Item>
            <Breadcrumb.Item>
              <Link to="/app/staff">GoTalk Staff</Link>
            </Breadcrumb.Item>
            <Breadcrumb.Item>Add New Staff</Breadcrumb.Item>
          </Breadcrumb>
        }
      />
      <Card>
        <StepsContainer justify="center">
          <Col span={20}>
            <Steps current={step}>
              <Step title="User Details" icon={submitting ? <LoadingOutlined /> : <UserOutlined />} />
              <Step title="Complete" icon={<CheckCircleOutlined />} />
            </Steps>
          </Col>
        </StepsContainer>
        <Row justify="center">
          {submitting ? <Col span={4}>
            <Spin />
          </Col> : (  
            <Col span="22">
              <Form
                {...layout}
                name="basic"
                initialValues={{ remember: true }}
                onFinish={handleSubmit}
                onFinishFailed={() => {}}
              >
                <Form.Item
                  label="Full Name"
                  name="name"
                  rules={[
                    { required: true, message: "Please input their name!" },
                  ]}
                >
                  <Input disabled={submitting} />
                </Form.Item>

                <Form.Item
                  label="Email Address"
                  name="email"
                  rules={[
                    {
                      required: true,
                      message: "Please input their email address!",
                    },
                    {
                      type: "email",
                      message: "Please enter a validate email!",
                    },
                  ]}
                >
                  <Input disabled={submitting} />
                </Form.Item>

                <Form.Item wrapperCol={{ offset: 20, span: 4 }}>
                  <Button type="primary" htmlType="submit" loading={submitting}>
                    Submit
                  </Button>
                </Form.Item>
              </Form>
            </Col>
          )}
        </Row>
      </Card>
    </div>
  );
};

export default AddStaff;
