import { gql } from '@apollo/client'

const InviteStaff = gql`
  mutation inviteAdmin(
    $email: String!
    $name: String!
  ) {
    inviteAdmin(
      data: {
        email: $email
        name: $name
      }
    ) {
        id
        name
        email
        emailVerified
    }
  }
`

export interface InviteStaffArgs {
  email: string;
  name: string;
}

export interface InviteStaffRes {
  inviteStaff: {
    id: string;
    name: string;
    email: string;
    emailVerified: boolean;
  }
}

export default InviteStaff