import React from 'react'
import AppBreadcrumb from 'components/layout-components/AppBreadcrumb';
import IntlMessage from '../util-components/IntlMessage';

interface Props {
	title: string;
	display: boolean;
	breadcrumbs?: JSX.Element;
	noTranslate?: boolean;
}

export const PageHeader = ({ title, display, breadcrumbs, noTranslate }: Props) => {
	return (
		display ? (
			<div className="app-page-header">
				<h3 className="mb-0 mr-3 font-weight-semibold">
					{noTranslate ? title : <IntlMessage id={title? title : 'home'}/>}
				</h3>
				{!!breadcrumbs ? breadcrumbs : <AppBreadcrumb />}
			</div>
		)
		: null
	)
}

export default PageHeader